import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Upgrade","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/getting-started/upgrade.md","filePath":"openshield-xdp/getting-started/upgrade.md","lastUpdated":1785906636000}'),n={name:"openshield-xdp/getting-started/upgrade.md"};function l(d,e,o,p,h,r){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h1><h2 id="automatic-updates-v2-16-recommended" tabindex="-1">Automatic updates (v2.16+, recommended) <a class="header-anchor" href="#automatic-updates-v2-16-recommended" aria-label="Permalink to &quot;Automatic updates (v2.16+, recommended)&quot;">​</a></h2><p>OpenShield-XDP ships with a signed auto-update channel. On licensed installs it is <strong>on by default</strong>: the loader checks for new releases every 6 hours and installs them unattended.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Manual, any time:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>What happens on every update (manual or automatic):</p><ol><li>The loader fetches the latest release metadata from the license server and verifies its <strong>Ed25519 signature</strong> (the same key that signs your license — a forged release notice fails verification).</li><li>The updates worker <strong>re-validates your license key</strong> and only then issues a 5-minute download URL. No license, no download.</li><li>The downloaded zip is checked against the <strong>signed SHA-256</strong> before anything is installed.</li><li>Current binaries are backed up, the new ones installed, and the service restarted. If the new build fails to come up, the previous version is <strong>restored automatically</strong>.</li></ol><p>Config (<code>/etc/openshield/openshield.yaml</code>):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">updates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # check for new releases + TUI badge</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # install automatically (licensed installs)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  endpoint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # override only for a self-hosted channel</span></span></code></pre></div><ul><li><code>enabled: true, auto: false</code> → you get a badge in the TUI top bar (<code>↑ v2.x.x</code>) and a log line; install with <code>sudo openshield update</code> when ready.</li><li>Unlicensed installs see the badge but are not served downloads.</li><li>Rollback manually if ever needed: the previous binaries are in <code>/opt/openshield/backup/&lt;version&gt;/</code>.</li></ul><h2 id="manual-upgrade-from-the-release-zip" tabindex="-1">Manual upgrade (from the release zip) <a class="header-anchor" href="#manual-upgrade-from-the-release-zip" aria-label="Permalink to &quot;Manual upgrade (from the release zip)&quot;">​</a></h2><p>If you prefer to inspect before installing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield-xdp-X.Y.Z.zip</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OpenShield-XDP</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Config struct changes</p><p>When upgrading between versions that change the <code>config</code> struct, stale pinned maps must be cleared. The installer handles this automatically. If you upgrade manually, run <code>sudo openshield fix</code> before loading.</p></div><h2 id="rolling-back" tabindex="-1">Rolling back <a class="header-anchor" href="#rolling-back" aria-label="Permalink to &quot;Rolling back&quot;">​</a></h2><p>An automatic update keeps the previous binaries under <code>/opt/openshield/backup/&lt;version&gt;/</code>. To roll back, copy them back over <code>/opt/openshield/bin/</code> and <code>/usr/local/bin/openshield</code>, then <code>sudo systemctl restart openshield-loader</code>.</p><h2 id="license-note" tabindex="-1">License note <a class="header-anchor" href="#license-note" aria-label="Permalink to &quot;License note&quot;">​</a></h2><p>Your license key is untouched by upgrades — it lives in <code>/etc/openshield/openshield.yaml</code> (<code>license.key</code>) with its cache at <code>/var/lib/openshield/license.json</code>. No reactivation is needed.</p>`,17)])])}const k=a(n,[["render",l]]);export{u as __pageData,k as default};
